/* User guidance is organized around handoffs, not a presentation script. */
(() => {
 const articles=[
  {id:'crm01',title:'CSKH chủ động & tài khoản nhân viên',role:'CSKH',summary:'Đúng người, đúng việc, đúng mốc chăm sóc.',why:'Chọn tài khoản demo trên thanh đầu trang. Chủ phòng khám xem toàn cảnh, bác sĩ xem lịch/hồ sơ phụ trách, CSKH xử lý hàng đợi, kế toán làm việc ở thu ngân. Patient 360 nối bối cảnh, không ghép mọi tác vụ vào cùng dashboard.',steps:['Chọn Mai Anh hoặc Thu để vào CSKH hôm nay. Lọc lý do, người phụ trách và hạn xử lý.','Mở task, đọc lịch sử, liệu trình còn lại và ngày dự kiến quay lại trước khi gọi.','Ghi kênh mô phỏng, kết quả, ghi chú và bước tiếp theo. Không nghe máy/bận cần giờ gọi lại.','Đồng ý đặt lịch: tiếp tục form đã điền đúng hồ sơ, xử lý xung đột rồi lưu. Chưa lưu lịch thì chưa hoàn tất task.','Phản hồi cần chuyên môn/khiếu nại được chuyển sang Theo dõi, bác sĩ phải xem.','Chủ phòng khám xem số task, tỷ lệ liên hệ và lịch đặt sau CSKH; chỉ check-in mới tính quay lại thực tế.'],handoff:'CRM ghi kết quả nội bộ, không tự gửi lời khuyên y khoa. Kênh Zalo/SMS/cuộc gọi đang mô phỏng; tài khoản demo không phải đăng nhập bảo mật.',links:[['crm','CSKH hôm nay'],['patients','Patient 360'],['schedule','Điều phối lịch']],related:['records','care','schedule']},
  {id:'system',title:'Hiểu hệ thống Pema',role:'Tất cả',summary:'Một hồ sơ xuyên suốt, nhiều điểm tiếp nối chăm sóc.',why:'Patient 360 là nơi nối các sự kiện của một người bệnh. Lịch hẹn tổ chức lần gặp; buổi điều trị ghi nhận việc đã làm; chăm sóc tại nhà và phản hồi giúp đội ngũ chuẩn bị cho lần gặp tiếp theo.',steps:['Tìm hồ sơ trước khi tạo mới để tránh chia lịch sử chăm sóc thành nhiều hồ sơ.','Đọc kế hoạch, mốc gần nhất và việc còn mở trước khi quyết định bước tiếp theo.','Thực hiện công việc ở màn phụ trách: điều phối ở Lịch, ghi chuyên môn ở Patient 360, phản hồi ở Theo dõi, thanh toán ở Thu ngân.','Sau khi lưu, kiểm tra kết quả ở hồ sơ và phần thông tin người bệnh nhìn thấy.'],handoff:'Mỗi lần bàn giao cần rõ: ai phụ trách, việc nào đã hoàn tất và bước tiếp theo là gì. Có lịch hẹn không có nghĩa đã điều trị; đã thu tiền không có nghĩa đã hoàn tất chăm sóc.',links:[['patients','Tìm hồ sơ'],['schedule','Xem lịch']],related:['schedule','clinical','care','billing']},
  {id:'roles',title:'Bắt đầu theo vai trò',role:'Tất cả',summary:'Biết nơi bắt đầu và người nhận bàn giao tiếp theo.',why:'Mỗi bộ phận làm việc trên cùng hành trình người bệnh, với mục tiêu và điểm kiểm tra riêng.',steps:['Lễ tân: tìm đúng hồ sơ → xếp lịch phù hợp → xác nhận hoặc check-in khi người bệnh đến.','Bác sĩ: mở Patient 360 → xem lịch sử, cảnh báo, ảnh và phản hồi → ghi nhận, duyệt kế hoạch và hướng dẫn.','Điều dưỡng / chăm sóc: theo dõi ảnh và cập nhật cần xử lý → chuyển bác sĩ xem khi cần → kiểm tra nội dung đã được phản hồi.','Thu ngân: kiểm tra đúng người bệnh, đúng hóa đơn → thu tiền → kiểm tra số còn lại và phiếu thu.','Người điều phối: xem tải bác sĩ/phòng → xử lý khoảng khóa → sắp lại lịch trước khi thay đổi khả năng phục vụ.'],handoff:'Đây là hướng dẫn phân công công việc; phiên bản hiện tại chưa áp dụng tài khoản và phân quyền theo vai trò.',links:[['today','Hàng đợi hôm nay'],['resources','Bác sĩ & phòng']],related:['records','schedule','billing']},
  {id:'records',title:'Hồ sơ & Patient 360',role:'Bác sĩ',summary:'Đọc bối cảnh trước khi ghi thêm một sự kiện.',why:'Danh sách bệnh nhân giúp tìm đúng người; Patient 360 giúp hiểu người đó đang ở đâu trong quá trình chăm sóc.',steps:['Vào Tìm bệnh nhân, tìm bằng tên, mã hồ sơ hoặc số điện thoại. Dùng bộ lọc để xem hồ sơ đang điều trị, có cảnh báo hoặc có hẹn.','Bấm Mở để kiểm tra thông tin nhận diện, bác sĩ phụ trách, cảnh báo và lịch hẹn tiếp theo.','Ở Tổng quan, đọc các mốc theo thời gian và thông tin cần nhớ; đối chiếu ảnh khi cần.','Chuyển sang Tư vấn, Kế hoạch, Buổi điều trị hoặc Ảnh trước / sau theo công việc.','Nếu cần hồ sơ mới, bấm Hồ sơ mới từ danh sách. Hồ sơ mới cần được khai thác tiền sử và thiết lập kế hoạch trước khi chăm sóc tiếp.'],handoff:'Lịch sử cho biết điều gì đã được ghi nhận và bởi ai. Tiến độ số buổi chỉ là số buổi hoàn tất, không phải tỷ lệ cải thiện da.',links:[['patients','Mở danh sách bệnh nhân']],related:['clinical','care','schedule']},
  {id:'schedule',title:'Lịch hẹn & tiếp đón',role:'Lễ tân',summary:'Ghép đúng người bệnh, dịch vụ, bác sĩ, phòng và thời gian.',why:'Lịch hẹn là một cam kết sử dụng nguồn lực. Mỗi lịch cần đủ thời gian thực hiện và chuẩn bị phòng, đồng thời không trùng lịch khác.',steps:['Vào Điều phối lịch. Chọn ngày hoặc 7 ngày, lọc bác sĩ/phòng để xem khả năng tiếp nhận.','Bấm Đặt lịch hoặc Xếp lịch ở danh sách chờ. Chọn bệnh nhân, dịch vụ, bác sĩ, phòng, ngày và giờ.','Dùng Tìm giờ trống nếu cần. Kiểm tra thời lượng, thời gian chuẩn bị và giá trước khi xác nhận.','Muốn dời lịch: mở thẻ để sửa, hoặc kéo sang ô mới. Kéo thả chỉ điền vị trí mới vào form; bấm Lưu thay đổi mới ghi nhận.','Mở thẻ để Xác nhận lịch. Khi người bệnh đến, dùng Check-in; không dùng check-in chỉ để xác nhận họ sẽ đến.','Nếu hủy, nhập lý do. Lịch đã hủy không chiếm chỗ và được giữ trong lịch sử hồ sơ.'],handoff:'Sau khi lưu, lịch đã đặt xuất hiện trong Patient Mobile; lịch sắp tới trên hồ sơ được tính lại. Check-in của ngày hiện tại đưa người bệnh vào trạng thái đang chờ để bàn giao cho phòng khám.',rules:['Trùng bác sĩ, người bệnh hoặc phòng: đổi giờ hoặc nguồn lực phù hợp.','Khoảng chuẩn bị vẫn chiếm phòng; vùng gạch chéo không phải giờ trống.','Ngoài ca, giờ nghỉ, phòng khóa hoặc dịch vụ tạm ngưng: cần chọn phương án khác.'],links:[['schedule','Mở điều phối lịch'],['today','Mở tiếp đón']],related:['resources','records','clinical']},
  {id:'resources',title:'Bác sĩ, phòng & dịch vụ',role:'Điều phối',summary:'Thiết lập điều kiện để lịch có thể thực hiện được.',why:'Thời lượng dịch vụ, phòng phù hợp và ca bác sĩ là đầu vào của điều phối. Điều chỉnh các điều kiện này cần tính tới những lịch đã cam kết.',steps:['Vào Bác sĩ & phòng, chọn ngày để xem số lịch và số phút điều trị của từng bác sĩ.','Bấm Xem lịch bác sĩ để chuyển sang lịch đã lọc.','Khi phòng cần bảo trì hoặc tạm không sử dụng, tạo khoảng khóa có ngày, giờ và lý do. Nếu đang vướng lịch, dời lịch trước rồi mới khóa.','Gỡ khóa khi phòng có thể hoạt động trở lại.','Vào Dịch vụ để sửa tên, giá, thời lượng, thời gian chuẩn bị hoặc tạm ngưng.'],handoff:'Thông số dịch vụ mới áp dụng cho lịch mới. Khi chỉ dời giờ/phòng, lịch cũ giữ thông số đã chốt; đổi dịch vụ trong lịch lấy thông số của dịch vụ mới.',rules:['Hiện ca bác sĩ là ca cố định, chưa có màn chỉnh ca hoặc nghỉ phép.','Khóa phòng là thao tác điều phối, không phải hủy tự động các lịch đã đặt.'],links:[['resources','Mở bác sĩ & phòng'],['services','Mở dịch vụ']],related:['schedule']},
  {id:'clinical',title:'Từ tư vấn đến buổi điều trị',role:'Bác sĩ',summary:'Biến một lần gặp thành bản ghi có thể tiếp tục sử dụng.',why:'Kế hoạch thể hiện hướng theo dõi. Buổi điều trị ghi lại đánh giá, việc đã thực hiện và hướng dẫn cho giai đoạn ở nhà.',steps:['Từ hồ sơ, xem tiền sử, cảnh báo, ảnh mốc và cập nhật chưa xử lý trước khi bắt đầu.','Ở Tư vấn, nhập ghi chú. Nếu tạo bản nháp AI, đọc, chỉnh sửa rồi mới Duyệt & lưu vào Patient 360.','Ở Kế hoạch, kiểm tra tên kế hoạch, tổng số buổi và số buổi đã hoàn tất. Điều chỉnh nếu cần.','Ở Buổi điều trị, nhập ngày, đánh giá trước buổi và hướng dẫn sau buổi. Nếu gắn ảnh, kiểm tra đồng ý ảnh và thông tin vùng/góc chụp.','Lưu buổi điều trị, sau đó kiểm tra sự kiện mới trong hành trình và hướng dẫn đã chuyển sang Patient Mobile.'],handoff:'Buổi đã lưu nối vào lịch sử và cập nhật số buổi hoàn tất. Hướng dẫn sau buổi là đầu vào của chăm sóc tại nhà. Nếu thiếu ảnh mốc, đội ngũ có mục theo dõi để bổ sung.',rules:['AI brief và ghi chú cần bác sĩ xem, sửa và duyệt; không tự ra chẩn đoán.','Ảnh và số buổi cần được đọc trong bối cảnh; không dùng làm kết luận tự động về hiệu quả.'],links:[['patients','Chọn hồ sơ để làm việc'],['studio','Mở ảnh trước / sau']],related:['records','care']},
  {id:'care',title:'Chăm sóc & phản hồi tại nhà',role:'Chăm sóc',summary:'Khép kín vòng phản hồi giữa người bệnh và phòng khám.',why:'Hành trình không kết thúc khi người bệnh rời phòng khám. Hướng dẫn và phản hồi giúp đội ngũ biết cần xem điều gì trước buổi tiếp theo.',steps:['Người bệnh mở Chăm sóc tại nhà để đọc hướng dẫn đã gửi và xác nhận đã đọc.','Người bệnh dùng Gửi cập nhật để mô tả tình trạng; có thể thêm ảnh và phải đồng ý cho sử dụng ảnh khi đính kèm.','Đội ngũ vào Theo dõi để xem các mục đang mở và người phụ trách; ưu tiên phản hồi cần bác sĩ xem.','Mở mục theo dõi, xem nội dung/ảnh, chỉnh phản hồi rồi Duyệt, phản hồi & đóng mục.','Kiểm tra phản hồi trong tin nhắn người bệnh và sự kiện tương ứng ở Patient 360.'],handoff:'Gửi cập nhật tạo việc cần xử lý. Duyệt và phản hồi mới hoàn tất vòng theo dõi; gửi thành công không đồng nghĩa bác sĩ đã xem.',rules:['Tin nhắn không phải kênh cấp cứu.','CRM01 tự lập task D1/D3/D7 cho session có protocol Laser CO2. Nhân viên xử lý; không tự gửi tin hoặc tự review lâm sàng.'],links:[['followups','Mở theo dõi']],related:['clinical','records','schedule']},
  {id:'billing',title:'Hóa đơn & thu tiền',role:'Thu ngân',summary:'Phân biệt khoản phải thu, tiền đã nhận và trạng thái chăm sóc.',why:'Thanh toán gắn với hóa đơn của người bệnh. Dữ liệu thu tiền giúp các bộ phận thống nhất số còn lại mà không suy diễn trạng thái điều trị.',steps:['Vào Thu ngân, chọn Tất cả, Còn phải thu hoặc Đã thanh toán. Dùng phân trang để xem thêm.','Đối chiếu người bệnh, mã hóa đơn, dịch vụ, tổng tiền và số đã thu.','Bấm Thu tiền, nhập số tiền thực nhận và chọn phương thức. Có thể thu một phần.','Xác nhận, rồi kiểm tra phiếu thu và số còn lại. Hóa đơn đủ tiền chuyển sang Đã thanh toán.','Người bệnh xem trạng thái tương ứng tại Hồ sơ → Tài liệu & hóa đơn.'],handoff:'Thu tiền cập nhật hóa đơn và phiếu thu. Thao tác này không tự đánh dấu một buổi điều trị hoàn tất và không thay đổi kế hoạch chuyên môn.',rules:['Số tiền phải dương và không vượt dư nợ; hóa đơn đã đủ không nhận thu thêm.','Hiện đặt lịch chưa tự tạo hóa đơn; chưa có phát hành hóa đơn mới, hoàn tiền hoặc kết nối ngân hàng.'],links:[['cashier','Mở thu ngân']],related:['records','clinical']},
  {id:'exceptions',title:'Khi cần kiểm tra lại',role:'Tất cả',summary:'Xử lý lỗi và hiểu phạm vi đang sử dụng.',why:'Khi hệ thống từ chối một thao tác, hãy đọc lý do và điều chỉnh dữ liệu đầu vào; không coi thông báo lỗi là đã lưu thành công.',steps:['Lịch bị trùng: xem bác sĩ, phòng, người bệnh và khoảng chuẩn bị; chọn giờ khác hoặc dùng Tìm giờ trống.','Không thể khóa phòng: kiểm tra lịch đã có trong khoảng đó và dời trước.','Không lưu được: giữ bản nháp, kiểm tra thông báo và thử lại. Không lặp thao tác thu tiền khi chưa kiểm tra phiếu thu.','Hai ứng dụng chưa khớp: mở Clinic Web và Patient Mobile trên cùng địa chỉ máy chủ và cùng hồ sơ trình duyệt; tải lại để kiểm tra.'],handoff:'Bản hiện tại phục vụ thử nghiệm nội bộ với dữ liệu giả lập, lưu trong trình duyệt. Chưa có đăng nhập/phân quyền thực, đồng bộ nhiều thiết bị, AI thật, SMS/Zalo, thanh toán hoặc vận hành sản xuất. Không nhập hồ sơ người bệnh thật.',links:[],related:['schedule','billing','care']}
 ];
 let current='system',query='';
 const e=s=>Pema.esc(s),normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();
 function navigation(){return articles.filter(a=>normalize(a.title+' '+a.role+' '+a.summary+' '+a.steps.join(' ')).includes(normalize(query))).map(a=>`<button class="guide-topic ${current===a.id?'active':''}" data-guide="${a.id}" aria-current="${current===a.id?'page':'false'}"><small>${e(a.role)}</small><strong>${e(a.title)}</strong></button>`).join('')||'<p class="notice">Không tìm thấy. Thử “lịch”, “thu tiền” hoặc tên vai trò.</p>';}
 function render(){const a=articles.find(a=>a.id===current);return `<div class="page-heading"><div><div class="eyebrow">Cách làm việc cùng Pema</div><h1 class="page-title">Hướng dẫn sử dụng</h1><p class="subtitle">Hiểu hành trình, làm đúng bước và bàn giao đủ thông tin.</p></div></div><div class="guide-layout"><aside class="guide-index"><label for="guide-search">Tìm chủ đề hoặc vai trò</label><input id="guide-search" type="search" value="${e(query)}" placeholder="Ví dụ: dời lịch, bác sĩ, thu tiền"><nav aria-label="Chủ đề hướng dẫn" id="guide-topics">${navigation()}</nav></aside><article class="guide-article"><div class="eyebrow">${e(a.role)}</div><h2 tabindex="-1" id="guide-title">${e(a.title)}</h2><p class="guide-lead">${e(a.summary)}</p>${a.id==='system'?`<div class="care-map" aria-label="Các bước trong hành trình chăm sóc">${[['records','Hồ sơ'],['schedule','Lịch hẹn'],['clinical','Điều trị'],['care','Chăm sóc'],['schedule','Tái khám']].map(([id,name],i)=>`<button data-guide="${id}"><small>0${i+1}</small>${name}<span aria-hidden="true">→</span></button>`).join('')}</div>`:''}<div class="guide-body"><section class="guide-instructions"><p>${e(a.why)}</p><h3>Cách thực hiện</h3><ol>${a.steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol></section><aside class="guide-context"><section class="guide-handoff"><h3>Thông tin đi tiếp như thế nào?</h3><p>${e(a.handoff)}</p></section>${a.rules?`<h3>Điểm cần nhớ</h3><ul>${a.rules.map(s=>`<li>${e(s)}</li>`).join('')}</ul>`:''}${a.links.length?`<div class="actions guide-actions">${a.links.map(([id,label])=>`<button class="btn btn-primary" data-nav="${id}">${e(label)} →</button>`).join('')}</div>`:''}</aside></div><footer class="guide-related"><h3>Đọc tiếp</h3>${a.related.map(id=>`<button class="btn" data-guide="${id}">${e(articles.find(a=>a.id===id).title)} →</button>`).join('')}</footer></article></div>`;}
 function bind(refresh){function topics(){document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>{current=b.dataset.guide;refresh();document.getElementById('guide-title').focus();});}topics();const search=document.getElementById('guide-search');if(search)search.oninput=()=>{query=search.value;document.getElementById('guide-topics').innerHTML=navigation();topics();};}
 window.PemaGuide={articles,render,bind};
})();
